endpoint.response:
{ success: true, message: string, data: {
    messages: ChatMessage[],      // ordine crescente per id
    has_more: bool,               // esistono messaggi piu' vecchi di messages[0]
    can_write: bool,              // false se commessa completed/closed
    can_moderate: bool,           // true solo per super-admin (D-10)
    unread_count: int,            // messaggi altrui con id > ultimo letto, non cancellati
    last_read_message_id: int|null,
    channel: string               // "work-orders.{id}.chat" (senza prefisso "private-")
} }
